mapper.select:
SELECT bs.id, bs.book_id AS bookId, b.title AS bookName, b.cover_url AS bookCover, b.author, b.publisher, bs.status, bs.create_time AS createTime, bs.update_time AS updateTime FROM book_shelf bs INNER JOIN book b ON b.id = bs.book_id WHERE bs.user_id = #{userId}
AND bs.status = #{status}
AND b.title LIKE CONCAT('%', #{bookName}, '%')
ORDER BY
b.title bs.create_time
ASC DESC , bs.id DESC
